  Definition w1_post (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (SP S1 ctx words n lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x28 x29 x30 x31 m1,
      ms' = MS (mkR (Z_to_bv 64 WO_SM_RA) (Z_to_bv 64 S1) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 S1) (Z_to_bv 64 480)
                    x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 (Z_to_bv 64 0x7fff8000) (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0)
                    (Z_to_bv 64 0) s10 (Z_to_bv 64 ctx) x28 x29 x30 x31) F (Z_to_bv 64 AFS_MALLOC_3) fc None m1 (seg_rom asegs)
      /\ munch [(S1, SP)] m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1 /\ stk asegs m1 lo SP
      /\ rw_cells asegs m1 (SP - 104) [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
      /\ rw_cells asegs m1 S1 [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 words); C8 (Z_to_bv 64 n)].

  Definition w1_sr (apo : bool) (r : Z) : list expr := srs sr_id ([(10%bv, EVar 32); (11%bv, ELit 0); (12%bv, EVar 33); (13%bv, EVar 34);
    (14%bv, ELit 0); (15%bv, ELit 0); (16%bv, ELit 0); (2%bv, EAlu ALU_ADD (EMd M_MUL (ELit 32) (EVar 35)) (ELit r))]
