  Lemma w1 : forall (apo : bool) (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (ctx words n lo : Z),
    (apo = false -> a7 = Z_to_bv 64 0) ->
    a0 = Z_to_bv 64 ctx -> a1 = Z_to_bv 64 0 -> a2 = Z_to_bv 64 words -> a3 = Z_to_bv 64 n ->
    a4 = Z_to_bv 64 0 -> a5 = Z_to_bv 64 0 -> a6 = Z_to_bv 64 0 ->
    0 <= ctx < 2 ^ 64 -> 0 <= words < 2 ^ 64 -> 0 <= n < 2 ^ 64 ->
    bv_unsigned sp mod 16 = 0 -> 2 ^ 45 <= bv_unsigned sp <= 2 ^ 47 ->
    stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - 512 ->
    mem_inv asegs m -> ACONST m ->
    evt asegs (w1_post ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc (bv_unsigned sp)
                 (bv_unsigned sp - 416 - bv_unsigned sp mod 32) ctx words n lo m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 (if apo then APO_ENTRY else AWO_ENTRY)) fc None m (seg_rom asegs)).
